// User progress state (solved/attempted status, last-submitted code) lives in
// a small SQLite file owned by this Next.js app, kept separate from the
// read-only extraction output in repo_root/data/ (which is regenerated by
// extract/ and must never be conflated with per-user runtime state).

import path from "node:path";
import fs from "node:fs";
import Database from "better-sqlite3";

const DB_DIR = path.join(process.cwd(), ".data");
const DB_PATH = path.join(DB_DIR, "progress.db");

function openDb(): Database.Database {
  fs.mkdirSync(DB_DIR, { recursive: true });
  const db = new Database(DB_PATH);
  db.pragma("journal_mode = WAL");
  db.exec(`
    CREATE TABLE IF NOT EXISTS progress (
      problemId TEXT PRIMARY KEY,
      status TEXT NOT NULL DEFAULT 'unattempted',
      lastLanguage TEXT,
      lastCode TEXT,
      updatedAt TEXT NOT NULL
    )
  `);
  return db;
}

declare global {
  // eslint-disable-next-line no-var
  var __progressDb: Database.Database | undefined;
}

export function getDb(): Database.Database {
  if (!globalThis.__progressDb) {
    globalThis.__progressDb = openDb();
  }
  return globalThis.__progressDb;
}

export type ProgressStatus = "solved" | "attempted" | "unattempted";

export interface ProgressRow {
  problemId: string;
  status: ProgressStatus;
  lastLanguage: string | null;
  lastCode: string | null;
  updatedAt: string;
}

export function getAllProgress(): ProgressRow[] {
  return getDb().prepare("SELECT * FROM progress").all() as ProgressRow[];
}

export function getProgress(problemId: string): ProgressRow | undefined {
  return getDb()
    .prepare("SELECT * FROM progress WHERE problemId = ?")
    .get(problemId) as ProgressRow | undefined;
}

// Upserts status, only ever moving it "forward" (unattempted -> attempted ->
// solved) unless explicitly overridden via setStatus -- so an accidental
// re-run of an already-solved problem that happens to fail once doesn't wipe
// the earlier solved mark.
export function recordAttempt(
  problemId: string,
  passed: boolean,
  language: string | null,
  code: string | null
): ProgressRow {
  const existing = getProgress(problemId);
  const rank: Record<ProgressStatus, number> = { unattempted: 0, attempted: 1, solved: 2 };
  const newStatus: ProgressStatus = passed ? "solved" : "attempted";
  const status =
    existing && rank[existing.status] > rank[newStatus] ? existing.status : newStatus;
  return upsert(problemId, status, language, code);
}

// Explicit user-driven override (manual mark, e.g. for non-judgeable problems).
export function setStatus(problemId: string, status: ProgressStatus): ProgressRow {
  const existing = getProgress(problemId);
  return upsert(problemId, status, existing?.lastLanguage ?? null, existing?.lastCode ?? null);
}

function upsert(
  problemId: string,
  status: ProgressStatus,
  lastLanguage: string | null,
  lastCode: string | null
): ProgressRow {
  const updatedAt = new Date().toISOString();
  getDb()
    .prepare(
      `INSERT INTO progress (problemId, status, lastLanguage, lastCode, updatedAt)
       VALUES (@problemId, @status, @lastLanguage, @lastCode, @updatedAt)
       ON CONFLICT(problemId) DO UPDATE SET
         status = excluded.status,
         lastLanguage = excluded.lastLanguage,
         lastCode = excluded.lastCode,
         updatedAt = excluded.updatedAt`
    )
    .run({ problemId, status, lastLanguage, lastCode, updatedAt });
  return getProgress(problemId)!;
}
